import {epoch,get,copy} from './transport.mjs'

const step=(fn,args)=>({fn,args})
const login=[step('go_to',{url:'https://flow.example.test/login'}),step('fill',{input:'#email',value:'synthetic-login@example.test'}),step('fill',{input:'#password',value:'SYNTHETIC_LOCAL_PASSWORD_LOGIN'}),step('click',{element:'button[type=submit]'}),step('wait_for_element',{element:'[data-synthetic=dashboard]'}),step('exists',{element:'[data-synthetic=dashboard]'})]
const signup=[step('go_to',{url:'https://flow.example.test/signup'}),step('fill',{input:'#email',value:'synthetic-signup@example.test'}),step('fill',{input:'#password',value:'SYNTHETIC_LOCAL_PASSWORD_SIGNUP'}),step('check',{checkbox:'#terms'}),step('select_radio',{radio:'sandbox'}),step('select',{select:'#plan',option:'sandbox'}),step('submit',{form:'#signup'}),step('exists',{element:'[data-synthetic=welcome]'})]
const recording=(steps,index)=>steps.map((value,i)=>({...value,guid:`00000000-0000-4000-8000-${String(index*100+i+1).padStart(12,'0')}`,contains_navigate:i===0||value.fn==='wpm_click'}))
const checkout=recording([step('wpm_go_to',{url:'https://flow.example.test/sandbox/checkout'}),step('wpm_click',{element:'#sandbox-payment',offsetX:0,offsetY:0}),step('wpm_wait',{seconds:'1'}),step('wpm_click',{element:'[data-synthetic=place-sandbox-order]',offsetX:0,offsetY:0}),step('wpm_contains_timeout',{element:'[data-synthetic=sandbox-receipt]',value:'Sandbox order accepted',waitTime:10,useRegularExpression:false})],3)
const unsupported=recording([step('wpm_go_to',{url:'https://flow.example.test/login'}),step('wpm_close_tab',{})],4)

export function addTransactions(c){
 const iso=time=>new Date(time*1000).toISOString()
 const details=[login,signup,checkout,unsupported].map((steps,i)=>({type:i<2?'script':'recording',name:['Synthetic login','Synthetic signup','Synthetic sandbox checkout','Synthetic unsupported command'][i],active:i!==3,interval:[5,10,20,60][i],region:['us-east','us-west','eu','au'][i],contact_ids:i===0?[71001,71002]:[],team_ids:i===0?[81001]:[],integration_ids:i===0?[91001,91002]:[],send_notification_when_down:2,severity_level:i%2?'low':'high',custom_message:i===0?'Synthetic outcome — café':'Synthetic transaction',status:['successful','failing','unknown','unknown'][i],created_at:epoch-90*86400,modified_at:epoch-86400,last_downtime_start:epoch-3700,last_downtime_end:epoch-3600,tags:['synthetic','transaction'],steps:copy(steps),...(i>=2?{metadata:{width:1440,height:900,disableWebSecurity:false,authentications:{httpAuthentications:[]}}}:{})}))
 const summaries=details.map((value,i)=>{const {name,active,interval,region,type,status,created_at,modified_at,last_downtime_start,last_downtime_end,tags}=value;return {id:83001+i,name,active,interval,region,type,status,created_at,modified_at,last_downtime_start,last_downtime_end,tags}})
 for(const offset of [0,2])c.add(`tms/list-${offset}.json`,'tms-list',{checks:summaries.slice(offset,offset+2),limit:2,offset},{recordCount:2,request:get('/api/3.1/tms/check',{limit:2,offset}),pagination:{limit:2,offset,...(offset===0?{nextOffset:2}:{})}})
 for(const [i,response] of details.entries())c.add(`tms/detail-${83001+i}.json`,'tms-detail',response,{sourceId:83001+i,request:get(`/api/3.1/tms/check/${83001+i}`)})
 c.add('tms/status-report.json','tms-status-report',{report:{check_id:83001,name:'Synthetic login',states:[{status:'up',from:iso(epoch-86400),to:iso(epoch-3700)},{status:'down',from:iso(epoch-3700),to:iso(epoch-3600),error_in_step:3,message:'Synthetic assertion failed'},{status:'up',from:iso(epoch-3600),to:iso(epoch)}]}},{sourceId:83001,recordCount:3,request:get('/api/3.1/tms/check/83001/report/status',{from:iso(epoch-86400),to:iso(epoch)})})
 c.add('tms/performance-report.json','tms-performance-report',{report:{check_id:83001,name:'Synthetic login',resolution:'day',intervals:[{from:iso(epoch-86400),average_response:850,downtime:100,uptime:86300,unmonitored:0,steps:login.map(value=>({average_response:100,step:copy(value)}))}]}},{sourceId:83001,request:get('/api/3.1/tms/check/83001/report/performance',{from:iso(epoch-86400),to:iso(epoch),resolution:'day',include_uptime:true})})
 return {details,summaries,counts:{tmsChecks:4,tmsScripts:2,tmsRecordings:2,tmsSupportedProposals:3,tmsUnsupportedCommands:1}}
}
